#include "resident/domains/interaction/interaction_source_projection.hpp"
// 入参不携带亲缘、人物prototype或答允结论；只请求原实际provider和明确作者模板。
#include "born_personal_dialogue_boundary.hpp"
#include <set>
namespace hanmo::resident {namespace {
void unique(const BoundaryValue& v,const StableId& path){std::set<StableId> keys;for(const auto& row:boundary::object(v,path))if(!keys.insert(row.first).second)boundary::fail("DuplicateBornPersonalDialogueField",path+"/"+row.first);}
}
Outcome<OpenBornPersonalDialogue> decode_born_personal_dialogue_command(const StableId& kind,const BoundaryValue& value){try{using namespace boundary;if(kind!="open_born_personal_dialogue")unsupported("UnsupportedBornPersonalDialogueCommand",kind);unique(value,kind);fields(value,{"provider_actor_id","template_id"},{},kind);OpenBornPersonalDialogue out{get_string(value,"provider_actor_id",kind),get_string(value,"template_id",kind)};if(out.provider_actor_id.empty()||out.provider_actor_id.size()>256||out.template_id.empty()||out.template_id.size()>256)fail("InvalidBornPersonalDialogueCommand",kind);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_born_personal_dialogue_command(const OpenBornPersonalDialogue& c){return boundary::obj({{"provider_actor_id",BoundaryValue{c.provider_actor_id}},{"template_id",BoundaryValue{c.template_id}}});}
BoundaryValue encode_born_personal_dialogue_quote(const BornPersonalDialogueQuote& q){return boundary::obj({{"duration",BoundaryValue{Integer{0}}},{"template_id",BoundaryValue{q.template_id}},{"provider_actor_id",BoundaryValue{q.context.provider_actor_id}},{"dialogue_id",BoundaryValue{q.dialogue_id}},{"place_id",BoundaryValue{q.context.place_id}}});}
Outcome<bool> decode_born_personal_dialogue_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{using namespace boundary;unique(scenario,"scenario");const auto* dynamic=scenario.find("dynamic_world");if(!dynamic)return {true,false,{}};unique(*dynamic,"dynamic_world");const auto* config=dynamic->find("born_personal_dialogues");if(!config)return {true,false,{}};if(get_string(*dynamic,"profile","dynamic_world")!="local_society_v1")unsupported("BornPersonalDialogueNativeProfileRequired","dynamic_world");unique(*config,"born_personal_dialogues");fields(*config,{"version","templates"},{},"born_personal_dialogues");if(get_int(*config,"version","born_personal_dialogues")!=1)unsupported("UnsupportedBornPersonalDialogueVersion","born_personal_dialogues");for(const auto* cap:{"born_personal_dialogues_v1","family_birth_v1","dialogue","multi_actor","native_dynamic_world"})if(std::find(capabilities.begin(),capabilities.end(),cap)==capabilities.end())unsupported("BornPersonalDialogueCapabilityRequired",cap);if(!scenario.find("family_birth")||!scenario.find("family_lineage")||!scenario.find("family_life"))unsupported("BornPersonalDialogueBirthProfileRequired","born_personal_dialogues");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_born_personal_dialogue_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const BornPersonalDialogueCatalog* catalog,const BornPersonalDialogueState* state){Integer own=0,birth=0,lineage=0,life=0;for(const auto& m:modules){if(m.first==born_personal_dialogue_module){++own;if(m.second!="1")return common_failure("UnsupportedBornPersonalDialogueVersion");}if(m.first=="family_birth"&&m.second=="1")++birth;if(m.first=="family_lineage"&&m.second=="1")++lineage;if(m.first=="family_life"&&m.second=="1")++life;}if(own!=(catalog?1:0)||bool(catalog)!=bool(state)||(catalog&&(catalog->version!=1||birth!=1||lineage!=1||life!=1))||(state&&state->version!=1))return common_failure("BornPersonalDialogueProfileMismatch");if(state)return common_success();for(const auto& h:common.state().facts.rows())if(h.second.domain==born_personal_dialogue_module||h.second.kind==born_personal_dialogue_opened_kind)return common_failure("BornPersonalDialogueProfileRequired",h.first);return validate_born_personal_dialogue_cached_results(common,nullptr);}
Outcome<bool> emit_born_personal_dialogue_fact_payload_fields(ProjectionWriter& w,const BornPersonalDialogueState* state,const FactRecord& h){if(h.domain!=born_personal_dialogue_module&&h.kind!=born_personal_dialogue_opened_kind)return {true,false,{}};if(!state||h.domain!=born_personal_dialogue_module||h.kind!=born_personal_dialogue_opened_kind)return {false,{},common_failure("BornPersonalDialogueFactMismatch",h.id).error};auto status=emit_born_personal_dialogue_fact_fields(w,*state,h.id,&h);if(!status.ok)return {false,{},status.error};return {w.status().ok,w.status().ok,w.status().error};}
Status emit_born_personal_dialogue_fact_payloads_fields(ProjectionWriter& w,const CommonStore& common,const BornPersonalDialogueState* state){std::size_t emitted=0;for(const auto& row:common.state().facts.rows()){const auto& h=row.second;if(h.domain!=born_personal_dialogue_module&&h.kind!=born_personal_dialogue_opened_kind)continue;if(!state||h.id!=row.first||h.domain!=born_personal_dialogue_module||h.kind!=born_personal_dialogue_opened_kind)return common_failure("BornPersonalDialogueFactMismatch",row.first);auto checked=w.object(row.first,h.field_order,[&](auto&out){return emit_born_personal_dialogue_fact_fields(out,*state,row.first,&h);});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->openings.size())return common_failure("BornPersonalDialogueFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> born_personal_dialogue_fact_payloads(const CommonStore& common,const BornPersonalDialogueState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_born_personal_dialogue_fact_payloads_fields(out,common,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_born_personal_dialogue_json_payloads(const CommonStore& common,const BornPersonalDialogueState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=born_personal_dialogue_fact_payloads(common,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"born_personal_dialogues/facts"))if(!compare_boundary(field(field(value,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("BornPersonalDialogueFactPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
